import sys
import math

def solve():
	inp = sys.stdin.readline
	q = int(inp())
	s = {0}
	d = {}
	for i in range(q):
		(t, x) = inp().split()
		if t == '+':
			s.add(int(x))
		elif t == '?':
			x = int(x)
			v = d.get(x, 0)
			while v in s:
				v += x
			d[x] = v
			print(v)
		else:
			raise Exception('wut')

def main():
	solve()
main()
